// F34 – rena länkar på hela luminusloom.net.
// Går igenom varje .html-fil under public/ och larmar om en intern länk slutar på .html,
// eftersom vercel.json har cleanUrls: "/besok-vreta", inte "/besok-vreta.html".
// Externa länkar (http, https, //), mailto:, tel: och ankare (#) räknas inte. Kommentarer räknas inte.
// Läser bara filer i public/; inget nätverk, inga hemligheter. Körs även av tests/kor-alla.cjs (F37).
// AI-skapat (B-051). Generated by AI, Directed by MS.
const fs = require('fs');
const path = require('path');

function htmlFiler(mapp) {
  return fs.readdirSync(mapp, { withFileTypes: true }).flatMap((d) => {
    const p = path.join(mapp, d.name);
    if (d.isDirectory()) return htmlFiler(p);
    return d.name.endsWith('.html') ? [p] : [];
  });
}

const intern = (v) => !/^(https?:|\/\/|mailto:|tel:|#)/i.test(v);
const html = (v) => /\.html(?:[?#].*)?$/i.test(v);

const fynd = [];
const filer = htmlFiler('public').sort();
for (const fil of filer) {
  const text = fs.readFileSync(fil, 'utf8').replace(/<!--[\s\S]*?-->/g, '');
  for (const m of text.matchAll(/href\s*=\s*["']([^"']+)["']/gi)) {
    if (intern(m[1]) && html(m[1])) fynd.push(`${fil}: ${m[1]}`);
  }
}

const vercel = JSON.parse(fs.readFileSync('vercel.json', 'utf8'));
const krav = {
  cleanUrlsPa: vercel.cleanUrls === true,
  harSidor: filer.length > 0,
  renaLankar: fynd.length === 0,
};
const ok = Object.values(krav).every(Boolean);
if (fynd.length) console.error('Länkar med .html:\n  ' + fynd.join('\n  '));
console.log(JSON.stringify({ ...krav, ok }));
process.exit(ok ? 0 : 1);
